{"id":"dapagliflozin","generic":"Dapagliflozin","trade":["Farxiga"],"cat":"Endocrine","sched":null,"cls":"SGLT2 inhibitor","ver":true,"cond":["t2dm","chf","ckd"],"boxed":[],"uses":["Improve glycemic control in type 2 diabetes","Reduce CV death and HF hospitalization in heart failure","Reduce progression of chronic kidney disease and CV/renal death","Reduce HF hospitalization in type 2 diabetes with CV risk"],"dA":["Type 2 diabetes: start 5 mg PO once daily in the morning; may increase to 10 mg.","Heart failure and CKD indications: 10 mg once daily.","With or without food; not for glycemic control if eGFR <45 (other indications to eGFR 25).","Assess volume status and correct hypovolemia before starting."],"dP":["Not routinely used in children."],"dur":"Long-term; once daily.","hl":"~12.9 hours","se":["Genital mycotic infections","Urinary tract infections","Euglycemic diabetic ketoacidosis","Volume depletion, hypotension, dizziness","Necrotizing fasciitis of the perineum (Fournier gangrene)","Hypoglycemia with insulin/sulfonylureas"],"ix":["Insulin — increased hypoglycemia; reduce insulin dose","Sulfonylureas — increased hypoglycemia; reduce secretagogue dose","Diuretics — additive volume depletion and hypotension","Lithium — may lower serum lithium levels; monitor"],"preg":"Not recommended in the 2nd/3rd trimesters (fetal renal development); insulin preferred. Breastfeeding not recommended (developing kidney).","pills":[{"f":"tablet","s":"5 mg","sh":"round","c":"yellow","im":"1427","sc":false},{"f":"tablet","s":"10 mg","sh":"diamond","c":"yellow","im":"1428","sc":false}],"src":["https://www.drugs.com/dosage/dapagliflozin.html","https://www.drugs.com/dapagliflozin.html"]},
{"id":"tirzepatide","generic":"Tirzepatide","trade":["Mounjaro","Zepbound"],"cat":"Endocrine","sched":null,"cls":"Dual GIP/GLP-1 receptor agonist","ver":true,"cond":["t2dm"],"boxed":["Thyroid C-cell tumors in rodents (human relevance unknown). Contraindicated with a personal or family history of medullary thyroid carcinoma (MTC) or MEN 2."],"uses":["Adjunct to diet/exercise to improve glycemic control in type 2 diabetes","Used when additional glycemic control beyond oral agents is needed"],"dA":["Start 2.5 mg subcutaneously once weekly (initiation dose, not for glycemic control).","After 4 weeks, increase to 5 mg once weekly.","Titrate in 2.5 mg increments every >=4 weeks as needed; maximum 15 mg once weekly.","Inject SC into abdomen, thigh, or upper arm; no renal or hepatic dose adjustment."],"dP":["Not routinely used in children."],"dur":"Long-term; once weekly.","hl":"~5 days (~117 h)","se":["Nausea, vomiting, diarrhea, constipation","Decreased appetite and abdominal pain","Acute pancreatitis","Gallbladder disease (cholelithiasis, cholecystitis)","Injection-site reactions and hypersensitivity","Hypoglycemia with insulin/sulfonylureas"],"ix":["Oral contraceptives — reduced efficacy from delayed gastric emptying; use backup for 4 weeks after start and each dose increase","Insulin — additive hypoglycemia; reduce insulin dose","Sulfonylureas — increased hypoglycemia; reduce secretagogue dose","Oral medications — delayed gastric emptying may alter absorption"],"preg":"May cause fetal harm based on animal data; insulin preferred in pregnancy. It delays gastric emptying and may reduce oral-contraceptive efficacy. No human-milk data; weigh benefits against risks.","pills":[{"f":"pen","s":"Single-dose pen and KwikPen; 2.5, 5, 7.5, 10, 12.5, 15 mg per 0.5 mL SC"}],"src":["https://www.drugs.com/dosage/tirzepatide.html","https://www.drugs.com/mounjaro.html"]}
